-- Sistem pembagian tugas penyebaran undangan WJNC.
-- Data undangan (451 baris) di-seed langsung dari file Excel "DAFTAR UNDANGAN
-- WJNC" — lihat blok insert di bagian bawah file ini.

create table if not exists undangan (
  id uuid primary key default gen_random_uuid(),
  kategori text not null check (kategori in ('vvip', 'vip_opd_mitra', 'wilayah_ormas', 'lansia_disabilitas_anak')),
  sub_kelompok text,
  nomor int,
  nama text not null,
  lokasi_parkir text,
  status text not null default 'belum' check (status in ('belum', 'selesai', 'kendala')),
  pic_user_id uuid references profiles(id) on delete set null,
  catatan text,
  bukti_url text,
  diperbarui_oleh uuid references profiles(id) on delete set null,
  diperbarui_at timestamptz,
  created_at timestamptz not null default now()
);

create index if not exists idx_undangan_pic on undangan(pic_user_id);
create index if not exists idx_undangan_kategori on undangan(kategori);

-- Pegawai biasa (PIC) cuma boleh mengubah status/catatan/bukti_url baris
-- miliknya sendiri — bukan nama/kategori/penugasan (itu hak admin saja).
create or replace function proteksi_undangan() returns trigger
language plpgsql as $$
begin
  if not is_admin() then
    new.kategori := old.kategori;
    new.sub_kelompok := old.sub_kelompok;
    new.nomor := old.nomor;
    new.nama := old.nama;
    new.lokasi_parkir := old.lokasi_parkir;
    new.pic_user_id := old.pic_user_id;
  end if;
  new.diperbarui_oleh := auth.uid();
  new.diperbarui_at := now();
  return new;
end;
$$;

drop trigger if exists trg_proteksi_undangan on undangan;
create trigger trg_proteksi_undangan
  before update on undangan
  for each row execute function proteksi_undangan();

alter table undangan enable row level security;

-- Semua yang login boleh lihat (dipakai admin buat dashboard progres
-- keseluruhan). Insert/delete hanya admin. Update: admin bebas, pegawai
-- biasa hanya baris yang PIC-nya dia sendiri (dibatasi trigger di atas).
create policy undangan_select on undangan for select to authenticated using (true);
create policy undangan_insert_admin on undangan for insert to authenticated with check (is_admin());
create policy undangan_delete_admin on undangan for delete to authenticated using (is_admin());
create policy undangan_update on undangan for update to authenticated
  using (is_admin() or pic_user_id = auth.uid());

